const summarize=values=>{if(!values.length)return null;const a=[...values].sort((a,b)=>a-b);return{mean:a.reduce((n,v)=>n+v,0)/a.length,max:a.at(-1),p95:a[Math.floor((a.length-1)*.95)],p99:a[Math.floor((a.length-1)*.99)]};};
export class FrameProfiler{
 constructor(){this.rows=new Map();this.last=null;this.webgl=false;this.viewport=null;this.memory=[];this.frames=0;}
 record(timestamp,cpuMs,sim,view){const elapsed=this.last===null?null:timestamp-this.last;this.last=timestamp;const stage=sim.plan?.stages[sim.stageIndex],motions=stage?.motions??[],name=sim.mode==='moving'&&motions.some(m=>(m.from.angle??0)!==(m.to.angle??0))?'rotation':sim.mode==='moving'&&motions.length>1?'simultaneous-moving':sim.mode;let rows=this.rows.get(name);if(!rows)this.rows.set(name,rows=[]);const real=!!view?.renderer?.isWebGLRenderer,info=view?.renderer?.info;this.webgl||=real;this.viewport=view?.renderer?.domElement?{width:view.renderer.domElement.width,height:view.renderer.domElement.height}:null;rows.push({frameMs:elapsed,cpuMs,drawCalls:real?info.render.calls:null,triangles:real?info.render.triangles:null,geometries:real?info.memory.geometries:null});if(rows.length>600)rows.shift();if(++this.frames%120===0&&performance.memory){this.memory.push({timestamp,heap:performance.memory.usedJSHeapSize});if(this.memory.length>60)this.memory.shift();}}
 report(){return{kind:'browser-frame-capture',webglVerified:this.webgl,viewport:this.viewport,frames:this.frames,rows:[...this.rows].map(([name,rows])=>{const frame=summarize(rows.map(r=>r.frameMs).filter(Number.isFinite));return{name,samples:rows.length,fps:this.webgl&&frame?1000/frame.mean:null,frameMs:this.webgl?frame:null,cpuMs:summarize(rows.map(r=>r.cpuMs)),drawCalls:summarize(rows.map(r=>r.drawCalls).filter(Number.isFinite)),triangles:summarize(rows.map(r=>r.triangles).filter(Number.isFinite))};}),memory:this.memory,gpuTimerMs:null,note:'Real requestAnimationFrame intervals and renderer.info only. CPU-only runs never imply FPS, and no GPU timer query or audio listening is claimed.'};}
}
